BEGIN;
-- Official sources reviewed 2026-10-05. Each row is a distinct application program.
-- Closed/unknown cycles remain labeled; future dates and eligibility are not invented.
CREATE TEMP TABLE expanded_catalog (
 slug text, name text, funder text, url text, summary text, eligibility text,
 notes text, min_award numeric, max_award numeric, rolling boolean, status text,
 deadline timestamptz, fee numeric, categories text[], applicants text[], country text, states text[]
) ON COMMIT DROP;
SELECT DISTINCT ON (s.funder) s.funder,s.url FROM expanded_catalog s
WHERE NOT EXISTS (SELECT 1 FROM funders f WHERE f.name=s.funder) ORDER BY s.funder,s.url;
minimum_award,maximum_award,rolling,application_status,deadline_at,application_fee,recurring,
discovered_at,last_checked_at,verification_status)
SELECT (SELECT id FROM funders f WHERE f.name=s.funder ORDER BY id LIMIT 1),s.name,s.slug,s.url,s.url,'grant',s.summary,s.eligibility,s.notes,
s.min_award,s.max_award,s.rolling,s.status,s.deadline,s.fee,true,
'2026-10-05T18:00:00-04:00','2026-10-05T18:00:00-04:00','recently_checked'
FROM expanded_catalog s ON CONFLICT(slug) DO NOTHING;
FROM expanded_catalog s JOIN opportunities o USING(slug) ON CONFLICT DO NOTHING;
FROM expanded_catalog s JOIN opportunities o USING(slug) ON CONFLICT DO NOTHING;
SELECT o.id,s.country,st.state FROM expanded_catalog s JOIN opportunities o USING(slug)
CROSS JOIN LATERAL unnest(s.states) AS st(state)
WHERE NOT EXISTS(SELECT 1 FROM opportunity_geographies g WHERE g.opportunity_id=o.id
AND g.country IS NOT DISTINCT FROM s.country AND g.state IS NOT DISTINCT FROM st.state);
COMMIT;
